#!/usr/bin/env bash
# Installs OpenSandbox 1.2.0 (server, osb CLI, MCP server) and starts the
# server in the background on localhost:8080, backed by your local Docker.
#
# The config is the project's own Docker example, generated by
# `opensandbox-server init-config`, plus three edits:
#   - server.api_key: without it the server refuses to start unless it runs in
#     an interactive terminal and you confirm the risk at a prompt.
#   - execd and egress images pinned to release-1.2.0. The 1.2.0 example still
#     ships execd v1.1.0 and egress v1.1.7. With execd v1.1.0, `osb command run`
#     prints every output line glued to the next one (no newlines).
#   - egress.mode = "dns+nft": Credential Vault (scenario 3) refuses to work in
#     the default "dns" mode, because DNS-only rules can be bypassed by
#     connecting to an IP directly. Scenarios 1 and 2 don't use the egress
#     sidecar at all, so the change doesn't affect them.
#
# Needs: Docker Engine on Linux, uv. Tested on Ubuntu 24.04, Docker 29.9.2.
set -euo pipefail

OSB_VERSION="1.2.0"
CONFIG="${SANDBOX_CONFIG_PATH:-$HOME/.sandbox.toml}"
LOG="$HOME/.opensandbox/server.log"
export PATH="$HOME/.local/bin:$PATH"

echo "==> Installing opensandbox-server, opensandbox-cli and opensandbox-mcp $OSB_VERSION"
uv tool install -q "opensandbox-server==$OSB_VERSION"
uv tool install -q "opensandbox-cli==$OSB_VERSION"
uv tool install -q "opensandbox-mcp==$OSB_VERSION"

if [ ! -f "$CONFIG" ]; then
  echo "==> Generating $CONFIG from the Docker example"
  opensandbox-server init-config "$CONFIG" --example docker
fi

if ! grep -q '^api_key' "$CONFIG"; then
  echo "==> Adding a random server.api_key"
  sed -i "/^\[server\]/a api_key = \"$(openssl rand -hex 16)\"" "$CONFIG"
fi
sed -i \
  -e "s#^execd_image = .*#execd_image = \"opensandbox/execd:release-$OSB_VERSION\"#" \
  -e "s#^image = \"opensandbox/egress:.*#image = \"opensandbox/egress:release-$OSB_VERSION\"#" \
  -e 's/^mode = "dns"$/mode = "dns+nft"/' \
  "$CONFIG"

echo "==> Starting the server (log: $LOG)"
mkdir -p "$(dirname "$LOG")"
nohup opensandbox-server --config "$CONFIG" > "$LOG" 2>&1 &
echo $! > "$HOME/.opensandbox/server.pid"

for _ in $(seq 1 30); do
  curl -fsS http://127.0.0.1:8080/health >/dev/null 2>&1 && break
  sleep 1
done
curl -fsS http://127.0.0.1:8080/health
echo

API_KEY="$(sed -n 's/^api_key = "\(.*\)"$/\1/p' "$CONFIG")"
cat <<EOF

==> Ready. osb, the Python SDK and the MCP server all read these:

export PATH="\$HOME/.local/bin:\$PATH"
export OPEN_SANDBOX_API_KEY=$API_KEY
export OPEN_SANDBOX_DOMAIN=localhost:8080
export OPEN_SANDBOX_PROTOCOL=http
EOF
